inline Profile Select(std::string const& move, std::string const& type, std::string const& category)
{
    if (auto it = Overrides.find(move); it != Overrides.end())
        return it->second;
    if (category == "Status")
        return PainProfile;
    if (category == "Physical")
    {
        auto it = Special.find(type);
        Profile result = it != Special.end() ? it->second : StrikeProfile;
        if (type == "NORMAL")
            result = StrikeProfile;
        result.lunge = true;
        result.windup = 360;
        return result;
    }
    auto it = Special.find(type);
    return it != Special.end() ? it->second : ArcaneBlastProfile;
}
